/* Per-profile appearance preferences. No remote account required. */
function validAccent(value){const s=String(value||'').trim();return /^#[a-f\d]{6}$/i.test(s)?s.toLowerCase():null}
function rgbHex(value){return [1,3,5].map(i=>parseInt(value.slice(i,i+2),16))}
function mixAccent(a,b,t){const x=rgbHex(a),y=rgbHex(b);return '#'+x.map((v,i)=>Math.round(v+(y[i]-v)*t).toString(16).padStart(2,'0')).join('')}
function luminanceAccent(hex){return rgbHex(hex).map(v=>{v/=255;return v<=.04045?v/12.92:((v+.055)/1.055)**2.4}).reduce((n,v,i)=>n+v*[.2126,.7152,.0722][i],0)}
function contrastAccent(a,b){const x=luminanceAccent(a),y=luminanceAccent(b);return (Math.max(x,y)+.05)/(Math.min(x,y)+.05)}
function accentText(a,bg){const target=luminanceAccent(bg)>.5?'#162033':'#ffffff';for(let i=0;i<=20;i++){const color=mixAccent(a,target,i/20);if(contrastAccent(color,bg)>=5.2)return color}return target}
function themePalette(a,dark){const neutral=dark?'#151515':'#faf9f7',bg=mixAccent(neutral,a,dark?.055:.018),surface=mixAccent(dark?'#202020':'#ffffff',a,dark?.07:.012),raised=mixAccent(dark?'#292929':'#f2f1ef',a,.055),ink=dark?'#f0eeeb':'#252422',muted=dark?'#b7b3ae':'#68645f';return {bg,surface,raised,ink,muted,line:mixAccent(surface,ink,dark?.15:.12),soft:mixAccent(surface,a,dark?.15:.08),text:accentText(a,raised),deep:dark?ink:mixAccent(a,'#252422',.72)}}
function applyAccent(){const a=validAccent(state.accent)||'#9a6544',dark=state.theme==='dark',p=themePalette(a,dark),root=document.documentElement,contrast=contrastAccent(a,'#ffffff')>=contrastAccent(a,'#202020')?'#ffffff':'#202020';for(const [key,value]of Object.entries(p))root.style.setProperty('--theme-'+key,value);for(const [key,value]of Object.entries({accent:a,'accent-text':p.text,'accent-on':contrast,'accent-soft':p.soft,green:p.text,deep:p.deep,bg:p.bg,white:p.surface,paper:p.surface,ink:p.ink,muted:p.muted,line:p.line,mint:p.soft}))root.style.setProperty('--'+key,value);root.style.colorScheme=dark?'dark':'light';document.querySelector('meta[name="theme-color"]')?.setAttribute('content',p.bg);document.body.classList.add('personalized');}

state.accent=validAccent(state.accent)||'#9a6544';
const settingsBeforeAccent=settingsView;settingsView=function(){return settingsBeforeAccent()+`<section class="panel appearance-panel"><span class="eyebrow">APPARENCE · JUSTE POUR TOI</span><h3>Choisis la couleur de ton espace.</h3><p>Une couleur principale, des fonds assortis. Ton choix s’applique à tout ton espace, en clair comme en sombre.</p><div class="accent-presets">${[['#9a6544','Cuivre'],['#356d9e','Bleu'],['#71629a','Prune'],['#55725f','Sauge'],['#a15d70','Rose']].map(([color,label])=>`<button class="accent-preset ${state.accent===color?'chosen':''}" data-accent="${color}" aria-pressed="${state.accent===color}" style="--swatch:${color}"><span aria-hidden="true"></span>${label}</button>`).join('')}</div><form id="accent-form"><label class="field" for="accent-hex">Ou ta propre couleur (code hexadécimal)</label><div class="accent-custom"><span class="accent-swatch" style="background:${state.accent}" aria-hidden="true"></span><input id="accent-hex" name="accent" maxlength="7" pattern="#[a-fA-F0-9]{6}" value="${state.accent}" placeholder="#9a6544" aria-describedby="accent-help" required><button class="secondary">Appliquer</button></div><small id="accent-help">Un # suivi de six chiffres ou lettres de A à F. Le contraste du texte s’adapte automatiquement.</small></form><button class="text-button" data-accent="#9a6544">Revenir à la couleur Nunya</button></section>`};
const renderBeforeAccent=render;render=function(){renderBeforeAccent();applyAccent()};
document.addEventListener('click',e=>{const b=e.target.closest('button[data-accent]');if(!b)return;e.stopImmediatePropagation();state.accent=validAccent(b.dataset.accent)||'#9a6544';persist();render();toast('Ta couleur est enregistrée sur cet appareil.')},true);
document.addEventListener('submit',e=>{if(e.target.id!=='accent-form')return;e.preventDefault();e.stopImmediatePropagation();const a=validAccent(new FormData(e.target).get('accent'));if(!a){toast('Utilise un code comme #9a6544.');return}state.accent=a;persist();render();toast('Ta nouvelle couleur est appliquée.')},true);
applyAccent();if(academySection==='profile')render();
